        // attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // read C's balance after withdrawal attempt
        uint afterC = address(c).balance;
        // read this contract's credit as observed by calling deposit then withdraw: C has no public getter for credit,
        // but we can observe that if withdrawAll() succeeded then the recorded credit for this contract in C must be zero
        // by depositing zero and then withdrawing: if credit were nonzero, withdrawAll would transfer further funds.
        // So we simulate observing credit by calling deposit with 0 and then attempting withdrawAll; however, calling state-modifying
