        // The asserted general rule: if not reverted then afterC == beforeC - amount and the credit was cleared (so further immediate withdraw would do nothing)

        // To check that credit is cleared without further modifying state we reason using only public observables: we assert that
        // if withdrawAll did not revert then C's balance decreased by exactly amount; that implies the contract sent amount out and cleared the credit.
        assert(reverted || (afterC + amount == beforeC));
    }

    receive() external payable { }
