        bool withdrewReverted;
        uint afterWithdrawC;
        uint afterWithdrawThis;
        try c.withdrawAll() {
            withdrewReverted = false;
            afterWithdrawC = address(c).balance;
            afterWithdrawThis = address(this).balance;
        } catch {
            withdrewReverted = true;
            afterWithdrawC = address(c).balance;
            afterWithdrawThis = address(this).balance;
        }

