        // Snapshot before any action
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Perform deposit (may be zero)
        c.deposit{value: depositAmount}();

        // Snapshot after deposit
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // Attempt first withdrawAll() if requested; catch revert
        bool firstReverted;
        uint afterFirstC;
        uint afterFirstThis;
        if (doFirstWithdraw) {
            try c.withdrawAll() {
                firstReverted = false;
                afterFirstC = address(c).balance;
                afterFirstThis = address(this).balance;
            } catch {
                firstReverted = true;
                afterFirstC = address(c).balance;
                afterFirstThis = address(this).balance;
            }
        } else {
            // If not doing the first withdraw, treat as no-op: state remains as after deposit
            firstReverted = true; // encode that no successful withdraw happened
            afterFirstC = afterDepositC;
            afterFirstThis = afterDepositThis;
        }

        // Now perform the probe: deposit(0) then attempt withdrawAll() to observe remaining recorded credit
        c.deposit{value: 0}();
        uint probeBeforeC = address(c).balance;
        uint probeBeforeThis = address(this).balance;

