        uint probeAfterC;
        uint probeAfterThis;
        try c.withdrawAll() {
            probeReverted = false;
            probeAfterC = address(c).balance;
            probeAfterThis = address(this).balance;
        } catch {
            probeReverted = true;
            probeAfterC = address(c).balance;
            probeAfterThis = address(this).balance;
        }

