        // - If the first withdraw was attempted and succeeded (firstReverted == false), then the probe withdraw must transfer no Ether (probeAfterC == probeBeforeC and probeAfterThis == probeBeforeThis).
        // - If the first withdraw was attempted and reverted (firstReverted == true because it reverted or we didn't attempt), then C's balance is unchanged from after the deposit (afterFirstC == afterDepositC).
        assert(
            (firstReverted == false ? (probeAfterC == probeBeforeC && probeAfterThis == probeBeforeThis) : (afterFirstC == afterDepositC))
        );
    }

